  }

  if (boon === 'protection') {
    pushEffect(world, actorId, { key: 'blessed', turnsLeft: 40, potency: 1, stacks: 1 });
    pushEffect(world, actorId, { key: 'regen', turnsLeft: desperate ? 24 : 16, potency: desperate ? 2 : 1, stacks: 1 });
