/**
 * Environment, navigation, interaction, deity, pet, companion, trap, weather, calendar wiring.
 * Lines ~325-330, ~1252-1407, ~1493-1683, ~1895-2037, ~2255-2355 from original.
 */
export function installEnvironmentMessages(ctx) {
  const { world, log, nameOfEntity, nameOfItem, bracketizeName, playerEntity,
          compGet, compHas, canSeeAt, resolveAmbientSoundText,
          isFavoredDeityForPlayer, Position, Devotion, NamedIdentity, Status } = ctx;

  function _playerHas(statusType) {
    const pe = playerEntity(world);
    if (!pe?.id || !Status) return false;
    const st = compGet(pe.id, Status);
    return Array.isArray(st?.statuses) && st.statuses.some((s) => s.type === statusType && (Number(s.duration || 0) | 0) > 0);
  }

  // === Ambient sound ===
  world.on('ambient:sound', (ev) => {
    const text = resolveAmbientSoundText(ev);
    if (!text) return;
    log(text, 'ambient');
  });

  // === Prayer events ===
  world.on('prayer', ({ actor, distress }) => {
    const who = nameOfEntity(actor);
    if (distress?.desperate) log(`${who} ${who === 'You' ? 'fall' : 'falls'} to ${who === 'You' ? 'your' : 'their'} knees and ${who === 'You' ? 'beg' : 'begs'} the heavens for mercy!`, 'deity');
    else if (distress?.troubled) log(`${who} ${who === 'You' ? 'clasp your' : 'clasps their'} hands and ${who === 'You' ? 'pray' : 'prays'} for aid...`, 'deity');
    else log(`${who} ${who === 'You' ? 'close your' : 'closes their'} eyes and ${who === 'You' ? 'whisper' : 'whispers'} a prayer.`, 'deity');
  });

  world.on('prayer:insight', ({ actor, deityName, pantheon, desperate, troubled, needs }) => {
    if (nameOfEntity(actor) !== 'You') return;
    const urgency = desperate ? 'desperate' : (troubled ? 'urgent' : 'steady');
    const needText = Array.isArray(needs) && needs.length ? ` Need: ${needs.join(', ')}.` : '';
    log(`${deityName || 'A voice from above'} hears your ${urgency} plea.${needText}`, 'deity');
  });

  world.on('prayer:curse-removed', ({ actor, name }) => {
    if (nameOfEntity(actor) !== 'You') return;
    log(`Warmth floods through ${bracketizeName(String(name || 'item'))} \u2014 the curse lifts like smoke.`, 'deity');
  });

  world.on('deity:patronShift', ({ playerId, deityName }) => {
    if (nameOfEntity(playerId) !== 'You') return;
    const label = bracketizeName(itemName);
    if (stage === 'off')    log(`Your ${label} smells off.`, 'system');
    if (stage === 'rancid') log(`Your ${label} reeks!`, 'system');
    if (stage === 'putrid') log(`Your ${label} is putrid!`, 'system');
  });

  world.on('item:equipped', ({ actor, itemId, slot, name }) => {
    const label = name ? bracketizeName(name) : `item ${itemId}`;
    log(`You equip ${label}${slot ? ' (' + slot + ')' : ''}.`, 'system');
    const info = compGet(itemId, ItemInfo);
    if (Array.isArray(info?.tags) && info.tags.includes('conflict')) {
      log('The dungeon erupts in discord \u2014 creatures turn on each other!', 'danger');
    }
  });
  world.on('item:unequipped', ({ actor, itemId, slot, name }) => {
    const label = name ? bracketizeName(name) : `item ${itemId}`;
    log(`You unequip ${label}${slot ? ' (' + slot + ')' : ''}.`, 'system');
  });
  world.on('item:welded', ({ actor, itemId, slot, name }) => {
    const label = name ? bracketizeName(name) : `item ${itemId}`;
    log(`You try to remove ${label}, but it is welded to you!`, 'danger');
  });

  world.on(UrnInteractionResolved, () => {
    log('The urn shatters, scattering ashes on the floor.', 'system');
  });

  // === Holy water on corpse ===
  world.on('corpse:holy_water', ({ actor, corpseName }) => {
    if (nameOfEntity(actor) !== 'You') return;
    const label = String(corpseName || 'corpse');
    log(`The ${label} corpse shudders. It looks more at peace.`, 'system');
  });

  // === Water splash (thrown water potion) ===
  world.on('water:splashed', ({ actor, waterType }) => {
    if (nameOfEntity(actor) !== 'You') return;
    const wt = String(waterType || 'plain');
    if (wt === 'holy') log('The bottle shatters. Blessed water soaks the area.', 'system');
    else if (wt === 'unholy') log('The bottle shatters. Unholy water soaks the area.', 'danger');
    else log('The bottle shatters. Water soaks the area.', 'system');
  });

  // === Curse events ===
  world.on('curse:equipment', ({ actor, itemId, source }) => {
    const pe = playerEntity(world);
    if (!pe || Number(actor || 0) !== pe.id) return;
    const name = bracketizeName(nameOfItem(itemId));
    if (source === 'scroll_cursing') return; // scroll:cursing handler covers this
    log(`${name} is surrounded by a black aura.`, 'danger');
  });
  world.on('curse:removed', ({ actor, itemId, name, source }) => {
    const pe = playerEntity(world);
    if (!pe || Number(actor || 0) !== pe.id) return;
    const label = bracketizeName(String(name || nameOfItem(itemId) || 'item'));
    log(`The black aura fades from ${label}.`, 'system');
  });

  // === Bad scroll messages (unhandled) ===
